const r = await $`grep -rlE "retryPolicy|maxAttempts: 3" src test`;
const files = r.stdout.split('\n').filter(Boolean);
for (const f of files) await $`sed -i '' -e 's/retryPolicy/backoffPolicy/g' -e 's/maxAttempts: 3/maxAttempts: 5/g' ${f}`;
const t = await $`node --test 2>&1 | tail -30`;
const left = await $`grep -rnE "retryPolicy|maxAttempts: 3" src test`;
return {files, left: left.stdout, test: t.stdout};

